UPDATE public.cms_resources SET content = E'To begin your publishing journey, you will need to submit a proposal and provide some initial documentation. This section brings together the key resources and forms that guide you through presenting your ideas for consideration and formalising the publication process.\n\n- **1.1 [Book Proposal Form](/downloads/CSP-1.1-Book-Proposal-Form.docx)** - Outline and submit your book ideas for consideration\n- **1.2 [Guidelines for Adapting PhD Thesis](/downloads/CSP-1.2-Guidelines-for-Adapting-PhD-Thesis.docx)** - How to convert a PhD thesis into a publishable book\n- **1.3 [Guidelines for Adapting Conference Proceedings](/downloads/CSP-1.3-Guidelines-for-Adapting-Conference-Proceedings.docx)** - How to convert conference proceedings into a publishable book\n- **1.4 [Contributor Agreement Form](/downloads/CSP-1.4-Contributor-Agreement-Form.docx)** - Outlining terms for the publication of a work with Cambridge Scholars Publishing.'
WHERE slug = 'proposal-and-publishing-forms';